add('04_002',3,'16:9，青居画面左侧中近景，武士在右后平台尽端形成小而宽的全身轮廓；稍低机位以斜向纵深连起二人，固定。','青扯回放下的双臂，身体仍向前弯着，大口喘过一次，牙关随即合紧；她目光留在远处武士身上，却先脱口想起春子。两绺长发因刚才下砸仍在胸侧摆动，最后垂直落下；武士双脚宽立，肩背在远处缓缓起伏。','灰绿石铺地面铺向右后，平台边缘形成低横线，上方蓝灰云天与稀薄米灰烟尘相接。','上方云天冷白漫射，青一侧从石面获得弱中性补光，远处武士在云天前呈深灰。','青喘息，头发扫衣，空旷风声穿过平台。',ja=['春子姉さんがいてくれたら…！'],tone='喘息间带焦急，提到姐姐时短促仰起，尾句留着未竟愿望。',kind='mixed',node={'青.姿态':'空手前倾喘息','武士.位置':'平台远端，尚未靠近'},meaning='近处喘息的青与远处宽立武士保留，借春子想到需要支援。',characters=['青','鬼头武士'],card={'opening':'怒意后身体负担重新显露。','beats':['喘一口、牙关合紧','目光盯武士，话却提到姐姐','发梢余动停下'],'coupling':'话从喘息里出来，求助念头不解除对敌警戒。','landing':'双方距离保持，青仍需自己作决定。'})
add('04_003',6,'16:9，武士头部极近景占画面中央偏右，裂隙中的白眼在中央偏下，左上仅留小块天空；固定斜侧机位，先看白眼再缓缓推近。','武士白眼在狭长裂隙里向青的方向转去，厚重头部缓慢下压，眼裂上沿收紧。第一问后停半拍，他的肩颈维持稳定，再低声说出侮辱性的威胁，最后白眼停住，视线牢牢钉在青的位置。','头部外缘与画面左上之间只有一小块蓝灰天空和淡灰云层，其余背景完全被主体遮住。','云天冷白漫射沿厚重头部弧面铺开，眼裂内部深黑，白眼亮度保持稳定。','低沉粗重的呼吸，平台风声在停顿中清楚露出。',ja=['…まだ戦意があるのか。','お前みたいな顔にぶっかけたら、さぞ気持ちいいだろうな。'],tone='语速悠缓，第一句试探，第二句带恶意侮辱，句尾压低。',kind='mixed',phase='state',meaning='狭缝白眼与威胁台词保留，身体维持远处对峙。',characters=['鬼头武士'],card={'opening':'武士把青的愤怒当成可戏弄的反应。','beats':['眼珠移向青，头部略压','问话后留半拍，再低声威胁'],'coupling':'视线定住形成压迫，语句间停顿令恶意沉下去。','landing':'仍在对峙距离，以目光等待青反应。'})
add('05_001',3,'16:9，青正面头肩近景，脸居画面中央，左右长发形成窄框；从微低机位平稳推至嘴角与眼神同框。','青眼睑向下压，嘴角绷开露出一边咬紧的齿缘；第一句从压着的气息中挤出。她下巴向前顶半寸，第二句说得更短、更硬，眼睛始终望着武士；话落后唇角重新收紧，肩部仍有轻微喘动。','银白长发两侧只留窄幅蓝灰天空，下方小段米灰烟尘渐淡。','正上方冷白柔光照脸，眼睑下压出浅灰影，旧擦痕保持原位。','短促鼻息，衣领随肩部呼吸轻擦，远处风声。',ja=['ド変態。','死んで。'],tone='第一句嫌恶地压低，第二句冷硬短斩，怒意留在咬紧的嘴角。',kind='mixed',phase='state',meaning='青半垂眼与咬牙嫌恶的原格表情保留。',characters=['青'],card={'opening':'受到侮辱后，她把情绪压成短句。','beats':['眼睑压低、露齿','下巴微顶，说完第二句收紧唇角'],'coupling':'短句分别落在两次呼气上，表情持续嫌恶。','landing':'敌意集中在对手，身体仍疲惫。'})
